<title>طلب خدمة صيانة | UNIFCO</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800;900&display=swap" rel="stylesheet">
<style>
:root{--navy:#071f4d;--red:#e3132c;--ink:#14233c;--muted:#748198;--line:#dce4ee;--soft:#f6f8fb;--green:#198754}*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:var(--ink);font-family:Cairo,Tahoma,Arial,sans-serif}.top{height:74px;background:#fff;border-bottom:1px solid #e3e8ef;display:flex;align-items:center}.top .wrap,.wrap{width:min(1180px,94%);margin:auto}.top .wrap{display:flex;align-items:center;justify-content:space-between}.logo{height:48px;width:auto}.back{font-size:12px;font-weight:800;color:var(--navy);text-decoration:none}.page-head{text-align:center;padding:30px 12px 18px}.page-head h1{margin:0;color:var(--navy);font-size:30px}.page-head p{margin:6px 0 0;color:var(--muted);font-size:12px}.panel{background:#fff;border:1px solid #e2e8f0;border-radius:14px;box-shadow:0 9px 28px rgba(7,31,77,.06);padding:18px;margin-bottom:13px}.service-line{display:grid;grid-template-columns:1fr 1fr 1.35fr;gap:10px;align-items:end}.field label,.section-title{display:block;font-size:11px;font-weight:900;color:var(--navy);margin-bottom:6px}.req{color:var(--red)}input,select,textarea{width:100%;height:42px;border:1px solid #ccd7e5;border-radius:7px;background:#fff;padding:8px 11px;color:#233754;font-family:inherit;font-size:11px;outline:none}input:focus,select:focus,textarea:focus{border-color:#7f9fca;box-shadow:0 0 0 3px #dce8f822}input[readonly]{background:#f3f6f9;color:#607086}.hint{font-size:9px;color:var(--muted);margin-top:5px}.future{display:none;background:#fff7e8;border:1px solid #f1d191;color:#845d13;border-radius:9px;padding:14px;margin-top:10px;font-size:11px;font-weight:700}.section-title{font-size:15px;margin:0 0 13px;display:flex;align-items:center;gap:8px}.num{width:24px;height:24px;border-radius:50%;background:var(--navy);color:#fff;display:inline-grid;place-items:center;font-size:10px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.span2{grid-column:span 2}.span4{grid-column:1/-1}.lookup-row{display:grid;grid-template-columns:1fr 160px;gap:8px}.btn{height:42px;border:0;border-radius:7px;padding:0 18px;background:var(--navy);color:#fff;font-family:inherit;font-weight:900;font-size:11px;cursor:pointer}.btn.red{background:var(--red)}.btn.ghost{background:#fff;color:var(--navy);border:1px solid #cdd8e6}.status{display:none;margin-top:9px;padding:9px 12px;border-radius:7px;font-size:10px;font-weight:800}.status.ok{display:block;background:#edf9f0;border:1px solid #a7dbb1;color:#16722d}.status.bad{display:block;background:#fff0f2;border:1px solid #f2b2bb;color:#b20d22}.disabled-section{opacity:.48;pointer-events:none}.map{height:190px;border:1px solid var(--line);border-radius:9px;overflow:hidden;background:#eef2f6;margin-top:10px}.map iframe{width:100%;height:100%;border:0}.asset-methods{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;margin-bottom:10px}.asset-method{height:39px;border:1px solid #cbd7e6;background:#fff;border-radius:7px;font:800 10px Cairo;color:var(--navy);cursor:pointer}.asset-method.active{border-color:var(--red);color:var(--red);background:#fff6f7}.asset-search{display:none;margin-bottom:10px}.asset-search.show{display:grid;grid-template-columns:1fr 140px;gap:8px}.asset-card{display:none;margin-top:10px;padding:12px;background:#f5f8fc;border:1px solid #dce5f0;border-radius:9px}.asset-card.show{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.asset-card div{font-size:9px;color:#7a879a}.asset-card b{display:block;font-size:10px;color:#1e3455;margin-top:2px}.manual{display:none}.manual.show{display:grid}.visit{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px}textarea{height:92px;resize:vertical}.uploads{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.upload{border:1px dashed #b9c9dd;border-radius:9px;background:#fafcff;padding:12px}.upload b{display:block;color:var(--navy);font-size:10px;margin-bottom:7px}.upload input{height:auto;border:0;padding:0;background:transparent;font-size:9px}.submit{width:100%;height:47px;background:var(--red);color:#fff;border:0;border-radius:8px;font:900 13px Cairo;cursor:pointer;margin:4px 0 20px}.privacy{text-align:center;color:#778399;font-size:9px;margin:-8px 0 13px}.hidden{display:none!important}@media(max-width:850px){.service-line,.grid,.visit,.uploads{grid-template-columns:1fr 1fr}.span4{grid-column:1/-1}.asset-methods{grid-template-columns:1fr 1fr}.asset-card.show{grid-template-columns:1fr 1fr}}@media(max-width:560px){.service-line,.grid,.visit,.uploads{grid-template-columns:1fr}.span2,.span4{grid-column:auto}.lookup-row,.asset-search.show{grid-template-columns:1fr}.asset-methods{grid-template-columns:1fr 1fr}.panel{padding:13px}.page-head h1{font-size:24px}}
</style>
</head>
<body>
<header class="top"><div class="wrap"><a href="{{ route('public.home') }}"><img class="logo" src="/brand/unifco-logo-v2.webp" alt="UNIFCO"></a><a class="back" href="{{ route('public.home') }}">العودة للرئيسية ←</a></div></header>
<div class="page-head"><h1>طلب خدمة</h1><p>النموذج الحالي مخصص لطلب صيانة عادية لعميل حالي ومسجل لدى UNIFCO.</p></div>
<main class="wrap">
<form action="{{ route('public.request.store') }}" method="post" enctype="multipart/form-data" id="maintenance-form">@csrf
<input type="hidden" name="request_intent" value="SERVICE_REQUEST"><input type="hidden" name="request_subtype" value="ROUTINE_MAINTENANCE"><input type="hidden" name="service_category" value="MAINTENANCE"><input type="hidden" name="urgency" value="NORMAL"><input type="hidden" name="lang" value="ar"><input type="hidden" name="asset_id" id="asset_id"><input type="hidden" name="latitude" id="latitude"><input type="hidden" name="longitude" id="longitude"><input type="hidden" name="site_address" id="site_address"><input type="hidden" name="asset_type" id="asset_type" value="GENERAL"><input type="hidden" name="equipment_brand" id="equipment_brand"><input type="hidden" name="equipment_model" id="equipment_model">
<section class="panel"><div class="service-line"><div class="field"><label>نوع الخدمة المطلوبة</label><select id="service-type"><option value="maintenance" selected>صيانة</option><option value="quotation">عرض سعر</option><option value="consultation">استشارة فنية</option></select></div><div class="field"><label>نوع الطلب</label><select id="service-subtype"><option value="routine" selected>صيانة عادية</option><option value="urgent">صيانة طارئة</option></select></div><div class="hint">يتم عرض نموذج صيانة عادية حاليًا. بقية النماذج سيتم تجهيزها لاحقًا.</div></div><div class="future" id="future-box">هذا النوع تم اعتماده للتطوير اللاحق. لم يتم تغيير أي نموذج آخر بالموقع.</div></section>
<div id="routine-form">
<section class="panel"><h2 class="section-title"><span class="num">1</span> بيانات العميل الحالي</h2><div class="grid"><div class="field span2"><label>رقم العميل <span class="req">*</span></label><div class="lookup-row"><input id="customer_number" placeholder="مثال: CUS-00125" autocomplete="off"><button type="button" class="btn" id="customer-lookup">جلب بيانات العميل</button></div><div class="status" id="customer-status"></div></div><div></div><div></div><div class="field"><label>اسم الشركة</label><input name="company_name" id="company_name" readonly required></div><div class="field"><label>اسم مسؤول التواصل</label><input name="responsible_person" id="responsible_person" readonly required></div><div class="field"><label>رقم التواصل</label><input name="mobile" id="mobile" readonly required></div><div class="field"><label>البريد الإلكتروني</label><input name="email" id="email" readonly required></div><div class="field"><label>المدينة</label><input id="customer_city" readonly></div><div class="field span2"><label>العنوان المختصر</label><input id="customer_address" readonly></div></div></section>
<section class="panel disabled-section" id="contract-section"><h2 class="section-title"><span class="num">2</span> بيانات العقد</h2><div class="grid"><div class="field span2"><label>رقم العقد <span class="req">*</span></label><select id="contract_no" required><option value="">اختر عقد العميل</option></select></div><div class="field"><label>نوع / عنوان العقد</label><input id="contract_title" readonly></div><div class="field"><label>حالة العقد</label><input id="contract_status" readonly></div></div></section>
<section class="panel disabled-section" id="site-section"><h2 class="section-title"><span class="num">3</span> الموقع والتواصل</h2><div class="grid"><div class="field span2"><label>الموقع المسجل <span class="req">*</span></label><select id="site_id" required><option value="">اختر الموقع</option></select></div><div class="field"><label>المدينة</label><input name="site_city" id="site_city" readonly required></div><div class="field"><label>اسم الموقع</label><input name="site_name" id="site_name" readonly required></div><div class="field span2"><label>العنوان</label><input id="visible_site_address" readonly></div><div class="field"><label>مسؤول الموقع</label><input id="site_contact" readonly></div><div class="field"><label>رقم التواصل</label><input id="site_mobile" readonly></div><input type="hidden" name="site_area" id="site_area" value="General"></div><div class="map" id="map"><iframe title="خريطة الموقع" src="about:blank"></iframe></div></section>
<section class="panel disabled-section" id="asset-section"><h2 class="section-title"><span class="num">4</span> المعدة وبياناتها</h2><div class="asset-methods"><button type="button" class="asset-method active" data-method="list">اختيار من معدات العقد</button><button type="button" class="asset-method" data-method="qr">مسح / إدخال QR</button><button type="button" class="asset-method" data-method="asset">رقم الأصل</button><button type="button" class="asset-method" data-method="serial">السيريال نمبر</button><button type="button" class="asset-method" data-method="manual">معدة غير تعاقدية</button></div><div id="asset-list-wrap" class="field"><label>المعدات المسجلة على العقد</label><select id="asset-list"><option value="">اختر المعدة</option></select></div><div class="asset-search" id="asset-search"><input id="asset-key" placeholder="أدخل القيمة أو امسح QR"><button type="button" class="btn ghost" id="asset-find">بحث عن المعدة</button></div><div class="asset-card" id="asset-card"><div>رقم الأصل<b id="ac-code">—</b></div><div>اسم المعدة<b id="ac-name">—</b></div><div>النوع<b id="ac-type">—</b></div><div>الشركة المصنعة<b id="ac-brand">—</b></div><div>الموديل<b id="ac-model">—</b></div><div>السيريال نمبر<b id="ac-serial">—</b></div><div>الموقع<b id="ac-site">—</b></div><div>الحالة التشغيلية<b id="ac-status">—</b></div></div><div class="grid manual" id="manual-fields"><div class="field"><label>اسم المعدة <span class="req">*</span></label><input id="manual_name"></div><div class="field"><label>نوع المعدة <span class="req">*</span></label><input id="manual_type"></div><div class="field"><label>الشركة المصنعة</label><input id="manual_brand"></div><div class="field"><label>الموديل</label><input id="manual_model"></div><div class="field"><label>السيريال نمبر</label><input id="manual_serial"></div></div></section>
<section class="panel"><h2 class="section-title"><span class="num">5</span> موعد الزيارة</h2><div class="visit"><div class="field"><label>تاريخ الزيارة المطلوب <span class="req">*</span></label><input type="date" name="requested_date" min="{{ now()->toDateString() }}" required></div><div class="field"><label>الوقت المطلوب <span class="req">*</span></label><input type="time" name="requested_time" required></div><div class="field"><label>الأولوية</label><select id="priority"><option value="NORMAL">عادية</option><option value="PRIORITY">مرتفعة</option></select></div></div></section>
<section class="panel"><h2 class="section-title"><span class="num">6</span> وصف سريع للعطل</h2><textarea name="details" required maxlength="5000" placeholder="اكتب وصفًا مختصرًا وواضحًا للعطل أو الخدمة المطلوبة..."></textarea></section>
<section class="panel"><h2 class="section-title"><span class="num">7</span> مرفقات الطلب</h2><div class="uploads"><label class="upload"><b>صور المشكلة</b><input type="file" name="problem_photos[]" accept="image/*" multiple></label><label class="upload"><b>صور المعدة</b><input type="file" name="equipment_photos[]" accept="image/*" multiple></label><label class="upload"><b>تقرير سابق (إن وجد)</b><input type="file" name="previous_reports[]" accept=".pdf,.xlsx,.xls,.doc,.docx,image/*" multiple></label></div></section>
<p class="privacy">بإرسال الطلب، سيتم استخدام بيانات العميل والأصل المسجلة لدى UNIFCO لمعالجة الطلب وربطه بالسجل التشغيلي الصحيح.</p><button class="submit" type="submit" id="submit-btn">إرسال طلب الخدمة</button>
</div></form></main>
<script>
(()=>{const $=id=>document.getElementById(id), apiCustomer='{{ route('public.current-maintenance.customer') }}', apiAssets='{{ route('public.current-maintenance.assets') }}';let customer=null,sites=[],contracts=[],assets=[];const status=$('customer-status');
const serviceType=$('service-type'),sub=$('service-subtype'),future=$('future-box'),routine=$('routine-form');function serviceChoices(){const v=serviceType.value;sub.innerHTML=v==='maintenance'?'<option value="routine">صيانة عادية</option><option value="urgent">صيانة طارئة</option>':v==='quotation'?'<option value="parts">عرض سعر قطع غيار</option><option value="contract">عرض سعر عقد صيانة</option><option value="visit">عرض سعر زيارة فنية</option>':'<option value="technical">استشارة فنية</option>';toggleRoutine()}function toggleRoutine(){const ok=serviceType.value==='maintenance'&&sub.value==='routine';routine.classList.toggle('hidden',!ok);future.style.display=ok?'none':'block'}serviceType.addEventListener('change',serviceChoices);sub.addEventListener('change',toggleRoutine);
$('priority').addEventListener('change',e=>document.querySelector('input[name="urgency"]').value=e.target.value);
$('customer-lookup').addEventListener('click',async()=>{status.className='status';status.textContent='جاري التحقق...';const no=$('customer_number').value.trim();if(!no){status.className='status bad';status.textContent='أدخل رقم العميل أولًا.';return}try{const r=await fetch(apiCustomer+'?customer_number='+encodeURIComponent(no),{headers:{Accept:'application/json'}}),d=await r.json();if(!r.ok)throw new Error(d.message||'تعذر جلب البيانات');customer=d.customer;sites=d.sites||[];contracts=d.contracts||[];$('company_name').value=customer.name||'';$('responsible_person').value=customer.contact_name||customer.name||'';$('mobile').value=customer.phone||'';$('email').value=customer.email||'';$('customer_city').value=customer.city||'';$('customer_address').value=customer.address||'';fillContracts();fillSites();['contract-section','site-section','asset-section'].forEach(id=>$(id).classList.remove('disabled-section'));status.className='status ok';status.textContent='تم جلب بيانات العميل بنجاح.'}catch(e){status.className='status bad';status.textContent=e.message;customer=null;['contract-section','site-section','asset-section'].forEach(id=>$(id).classList.add('disabled-section'))}});
function fillContracts(){const el=$('contract_no');el.innerHTML='<option value="">اختر عقد العميل</option>'+contracts.map(c=>`<option value="${esc(c.contract_no||'')}" data-id="${c.id}">${esc(c.contract_no||'بدون رقم')} — ${esc(c.title||'عقد خدمة')}</option>`).join('')}function fillSites(){const el=$('site_id');el.innerHTML='<option value="">اختر الموقع</option>'+sites.map(s=>`<option value="${s.id}">${esc(s.name||s.site_code||'موقع')} — ${esc(s.city||'')}</option>`).join('')}
$('contract_no').addEventListener('change',async e=>{const c=contracts.find(x=>(x.contract_no||'')===e.target.value);$('contract_title').value=c?.title||'';$('contract_status').value=c?.status||'';await loadAssets()});$('site_id').addEventListener('change',async e=>{const s=sites.find(x=>String(x.id)===e.target.value);$('site_name').value=s?.name||'';$('site_city').value=s?.city||'';$('site_area').value=s?.city||'General';$('visible_site_address').value=s?.address||'';$('site_address').value=s?.address||'';$('site_contact').value=s?.contact_name||'';$('site_mobile').value=s?.contact_mobile||'';$('latitude').value=s?.latitude||'';$('longitude').value=s?.longitude||'';setMap(s);await loadAssets()});
function setMap(s){const f=$('map').querySelector('iframe');if(!s?.latitude||!s?.longitude){f.src='about:blank';return}const lat=Number(s.latitude),lon=Number(s.longitude),d=.025;f.src=`https://www.openstreetmap.org/export/embed.html?bbox=${lon-d}%2C${lat-d}%2C${lon+d}%2C${lat+d}&layer=mapnik&marker=${lat}%2C${lon}`}
async function loadAssets(key=''){if(!customer)return;const p=new URLSearchParams({customer_id:customer.id});if($('contract_no').value)p.set('contract_no',$('contract_no').value);if($('site_id').value)p.set('site_id',$('site_id').value);if(key)p.set('key',key);const r=await fetch(apiAssets+'?'+p.toString(),{headers:{Accept:'application/json'}}),d=await r.json();assets=d.assets||[];if(!key){$('asset-list').innerHTML='<option value="">اختر المعدة</option>'+assets.map(a=>`<option value="${a.id}">${esc(a.asset_code||'')} — ${esc(a.name||a.asset_type||'معدة')}</option>`).join('')}return assets}
$('asset-list').addEventListener('change',e=>selectAsset(assets.find(a=>String(a.id)===e.target.value)));$('asset-find').addEventListener('click',async()=>{const found=await loadAssets($('asset-key').value.trim());if(found.length)selectAsset(found[0]);else{alert('لم يتم العثور على معدة مطابقة لهذا العميل والعقد/الموقع المحدد.')}});
document.querySelectorAll('.asset-method').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.asset-method').forEach(x=>x.classList.remove('active'));b.classList.add('active');const m=b.dataset.method;$('asset-list-wrap').style.display=m==='list'?'block':'none';$('asset-search').classList.toggle('show',['qr','asset','serial'].includes(m));$('manual-fields').classList.toggle('show',m==='manual');$('asset-card').classList.toggle('show',false);if(m==='manual'){$('asset_id').value='';$('asset_type').value=$('manual_type').value||'GENERAL'}$('asset-key').placeholder=m==='qr'?'امسح QR أو ألصق محتواه':m==='serial'?'أدخل السيريال نمبر':'أدخل رقم الأصل'}));
['manual_name','manual_type','manual_brand','manual_model'].forEach(id=>$(id).addEventListener('input',()=>{$('asset_type').value=$('manual_type').value||$('manual_name').value||'GENERAL';$('equipment_brand').value=$('manual_brand').value;$('equipment_model').value=$('manual_model').value}));function selectAsset(a){if(!a)return;$('asset_id').value=a.id;$('asset_type').value=a.asset_type||a.asset_category||a.name||'GENERAL';$('equipment_brand').value=a.manufacturer||'';$('equipment_model').value=a.model_no||'';$('ac-code').textContent=a.asset_code||'—';$('ac-name').textContent=a.name||'—';$('ac-type').textContent=a.asset_type||a.asset_category||'—';$('ac-brand').textContent=a.manufacturer||'—';$('ac-model').textContent=a.model_no||'—';$('ac-serial').textContent=a.serial_no||a.manufacturer_asset_number||'—';$('ac-site').textContent=a.site_name||'—';$('ac-status').textContent=a.operational_status||'—';$('asset-card').classList.add('show')}
$('maintenance-form').addEventListener('submit',e=>{if(!customer){e.preventDefault();alert('يرجى إدخال رقم العميل وجلب بياناته أولًا.');return}if(!$('contract_no').value){e.preventDefault();alert('يرجى اختيار العقد.');return}if(!$('site_id').value){e.preventDefault();alert('يرجى اختيار الموقع.');return}const manual=$('manual-fields').classList.contains('show');if(!manual&&!$('asset_id').value){e.preventDefault();alert('يرجى اختيار المعدة أو البحث عنها.');return}if(manual&&!$('manual_name').value.trim()){e.preventDefault();alert('يرجى إدخال بيانات المعدة غير التعاقدية.')}});function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}})();
</script>
</body></html>
